  );

  Map<String, dynamic> toJson() => _stripNulls({
    "expectedResponseDigest": expectedResponseDigest,
    "operation": componentConformanceOperationValues.reverse[operation],
    "requestDigest": requestDigest,
    "requestJson": requestJson,
    "token": token,
  });
}

