    required this.runId,
    required this.steps,
    required this.suiteDigest,
    required this.workflowId,
  });

  factory PlanClass.fromJson(Map<String, dynamic> json) => PlanClass(
    actionExecutionId: json["actionExecutionId"],
    artifactDigest: json["artifactDigest"],
